  name: { get: sec => sec.name || '' },
  groupCount: { get: sec => getMajorOfferingSectionGroupCount(sec), type: 'number' },
  offeringUnit: { get: sec => resolveGeOfferingSectionOfferingUnit(sec) },
  credits: { get: sec => sec.credits, type: 'number' },
