  if (title) title.textContent = `单位时间设置 · ${term || ''}`;
  const hint = document.getElementById('schedule-unit-time-hint');
  if (hint) {
    hint.innerHTML = `<span class="legend-item">按学院覆盖本学期排课起止时间与师生查看课表开始时间；未配置的学院沿用学期默认时间</span>`;
  }
